{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "Field",
    "displayName": "Field",
    "group": "Field",
    "category": "Form Controls",
    "keywords": [
      "field",
      "formfield",
      "formgroup",
      "formcontrol",
      "label",
      "input",
      "required",
      "optional",
      "helpertext",
      "hint"
    ],
    "playground": {
      "defaults": {
        "label": "Email address",
        "inputID": "email-input",
        "description": "Use Field for controls that do not already provide field under the hood.",
        "descriptionID": "email-help",
        "children": {
          "__element": "input",
          "props": {
            "id": "email-input",
            "aria-describedby": "email-help",
            "placeholder": "you@example.com",
            "type": "email"
          }
        }
      }
    },
    "theming": {
      "targets": [
        {
          "className": "astryx-field",
          "visualProps": [
            "layout"
          ]
        },
        {
          "className": "astryx-field-label"
        },
        {
          "className": "astryx-field-status",
          "visualProps": [
            "type",
            "variant"
          ]
        },
        {
          "className": "astryx-input-status-icon",
          "visualProps": [
            "size",
            "status"
          ]
        },
        {
          "className": "astryx-input-clear-button"
        },
        {
          "className": "astryx-input-clear-icon"
        }
      ],
      "vars": [
        {
          "name": "--_field-radius",
          "description": "Border radius of input fields",
          "default": "var(--radius-element)",
          "private": true
        },
        {
          "name": "--_field-status-overlap",
          "description": "Amount an attached FieldStatus extends behind the lower half of the control. Set from the rendered control size.",
          "default": "calc(var(--size-element-md) / 2)",
          "private": true
        }
      ],
      "derived": [
        {
          "property": "borderRadius",
          "vars": [
            "--_field-radius"
          ]
        }
      ]
    },
    "description": "Low-level form field wrapper for custom controls that need a label, description, and optional/required indicators.",
    "props": [
      {
        "name": "label",
        "type": "string",
        "description": "Label text for the field (always rendered for accessibility).",
        "required": true
      },
      {
        "name": "inputID",
        "type": "string",
        "description": "ID for the input element (used for the label htmlFor attribute).",
        "required": true
      },
      {
        "name": "labelID",
        "type": "string",
        "description": "ID applied to the label element itself for group accessibility."
      },
      {
        "name": "isGroupLabel",
        "type": "boolean",
        "description": "Renders the label as a span for control groups (radiogroup, checkbox list).",
        "default": "false"
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "The input or control to render.",
        "required": true
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Visually hide the label (still accessible to screen readers).",
        "default": "false"
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Whether the associated input is disabled. Propagates disabled styling to the label.",
        "default": "false"
      },
      {
        "name": "description",
        "type": "string",
        "description": "Description text displayed between the label and input."
      },
      {
        "name": "descriptionID",
        "type": "string",
        "description": "ID for the description element (use for aria-describedby on the input)."
      },
      {
        "name": "isOptional",
        "type": "boolean",
        "description": "Whether the field is optional (mutually exclusive with isRequired).",
        "default": "false"
      },
      {
        "name": "isRequired",
        "type": "boolean",
        "description": "Whether the field is required (mutually exclusive with isOptional).",
        "default": "false"
      },
      {
        "name": "labelIcon",
        "type": "ReactNode | IconType",
        "description": "Icon to display before the label text. See `astryx docs icons` for valid semantic names."
      },
      {
        "name": "labelTooltip",
        "type": "string",
        "description": "Help text for an info button after the label, named \"About {label}\". Hover and keyboard focus preview it; a tap, click, Enter, or Space opens it and never focuses or toggles the control."
      },
      {
        "name": "status",
        "type": "{type: 'warning' | 'error' | 'success', message?: string, messageID?: string}",
        "description": "Status indicator with type and optional message. When message is set, displays a colored status box. messageID is for wiring aria-describedby on the input."
      },
      {
        "name": "statusVariant",
        "type": "'attached' | 'detached' | 'tooltip'",
        "description": "How status feedback is placed. Attached overlaps an eligible opaque, bordered, fixed-height control; detached renders a message below custom or non-bordered controls; tooltip leaves the visible affordance to the wrapped input and announces its message without a FieldStatus box.",
        "default": "'attached'"
      },
      {
        "name": "width",
        "type": "SizeValue",
        "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned. Prefer this over setting width via xstyle/className/style, which only size the inner control box. Without a width, a row can shrink the whole field below the natural width of its control, so filter bars shrink instead of overflowing."
      },
      {
        "name": "ref",
        "type": "React.Ref<HTMLDivElement>",
        "description": "Ref forwarded to the root element."
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning, sizing). Must be a stylex.create() value: not an inline style object like style={{}}."
      },
      {
        "name": "className",
        "type": "string",
        "description": "CSS class name(s) appended to the root element. Prefer xstyle for StyleX deduplication."
      },
      {
        "name": "style",
        "type": "React.CSSProperties",
        "description": "Inline styles applied to the root element. Takes priority over StyleX inline styles."
      }
    ],
    "components": [
      {
        "name": "FieldLabel"
      },
      {
        "name": "FieldStatus"
      }
    ],
    "usage": {
      "description": "Field is a low-level wrapper for custom, native, or third-party controls that do not already provide field label, description, and status UI. Use it when you need the Field shell around a control you own; use styled Astryx inputs like TextInput, Typeahead, and Select directly when they already expose label, description, and validation props.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Wrap custom controls, native inputs, or third-party widgets that need labeling, helper text, optional/required indicators, or validation status."
        },
        {
          "guidance": true,
          "description": "Always provide a label for accessibility, even if visually hidden with isLabelHidden."
        },
        {
          "guidance": true,
          "description": "Use inputID and descriptionID to connect the label and description to the inner control with htmlFor and aria-describedby."
        },
        {
          "guidance": false,
          "description": "Nest Field around styled inputs such as TextInput, Typeahead, Select, DateInput, or TextArea; those components already render their own Field shell."
        },
        {
          "guidance": true,
          "description": "Use attached status only when the wrapped control is opaque, bordered, and fixed-height; use detached for custom, tall, translucent, or non-bordered controls."
        },
        {
          "guidance": false,
          "description": "Set both isOptional and isRequired on the same field."
        },
        {
          "guidance": false,
          "description": "Hide the label without providing an alternative way for the user to understand the field purpose."
        }
      ],
      "anatomy": [
        {
          "name": "Container",
          "required": true,
          "description": "Root field box that owns layout, width, and local stacking for the label, control, and status."
        },
        {
          "name": "Label",
          "required": true,
          "description": "Text identifying the field. Always rendered for accessibility, optionally hidden visually."
        },
        {
          "name": "Ordinary description",
          "required": false,
          "description": "Helper text under the label in the ordinary field layout."
        },
        {
          "name": "Horizontal-label description",
          "required": false,
          "description": "Helper text in the control column when FormLayout owns horizontal labels."
        },
        {
          "name": "Control slot",
          "required": true,
          "description": "A custom, native, or third-party control that does not already render a field shell."
        },
        {
          "name": "Status message",
          "required": false,
          "description": "Inline validation feedback showing error, warning, or success with a message."
        },
        {
          "name": "Input status icon",
          "required": false,
          "description": "Shared status affordance used by Field-composed input controls."
        },
        {
          "name": "Input clear button",
          "required": false,
          "description": "Shared clear action used by Field-composed input controls."
        },
        {
          "name": "Input clear icon",
          "required": false,
          "description": "Glyph inside the shared input clear action."
        },
        {
          "name": "Optional/Required indicator",
          "required": false,
          "description": "Badge next to the label showing whether the field is optional or required."
        },
        {
          "name": "Label tooltip trigger",
          "required": false,
          "description": "Info icon beside the label that opens explanatory content."
        },
        {
          "name": "Label tooltip surface",
          "required": false,
          "description": "Layer-hosted explanatory content for the label tooltip."
        }
      ]
    },
    "examples": [
      {
        "label": "Filter bar",
        "code": "\nimport {useState} from 'react';\nimport {HStack} from '@astryxdesign/core/HStack';\nimport {Icon} from '@astryxdesign/core/Icon';\nimport {Selector} from '@astryxdesign/core/Selector';\nimport {StackItem} from '@astryxdesign/core/Stack';\nimport {TextInput} from '@astryxdesign/core/TextInput';\n\n// Every Field-based input (TextInput, Selector, DateInput, ...) can be shrunk\n// by its row, so a filter bar never pushes the page sideways. Let the row wrap\n// so that on a phone the search box keeps a full line and the selectors move\n// below it; on wider screens everything stays on one line, with the search box\n// taking the free space.\nfunction OrdersFilterBar() {\n  const [query, setQuery] = useState('');\n  const [status, setStatus] = useState('Awaiting fulfillment');\n  const [region, setRegion] = useState('All regions');\n  const [sort, setSort] = useState('Newest first');\n  return (\n    <HStack gap={2} wrap=\"wrap\" vAlign=\"center\">\n      <StackItem size=\"fill\">\n        <TextInput\n          label=\"Search orders\"\n          isLabelHidden\n          placeholder=\"Search by order or customer\"\n          startIcon={<Icon icon=\"search\" />}\n          value={query}\n          onChange={setQuery}\n        />\n      </StackItem>\n      <Selector\n        label=\"Status\"\n        isLabelHidden\n        options={['All statuses', 'Awaiting fulfillment', 'Shipped', 'Delivered', 'Returned']}\n        value={status}\n        onChange={setStatus}\n      />\n      <Selector\n        label=\"Region\"\n        isLabelHidden\n        options={['All regions', 'North America', 'Europe', 'Asia Pacific']}\n        value={region}\n        onChange={setRegion}\n      />\n      <Selector\n        label=\"Sort\"\n        isLabelHidden\n        options={['Newest first', 'Oldest first', 'Highest total']}\n        value={sort}\n        onChange={setSort}\n      />\n    </HStack>\n  );\n}\n"
      },
      {
        "label": "Wrap a custom control",
        "code": "\nfunction CustomSliderField() {\n  return (\n    <Field\n      label=\"Confidence\"\n      inputID=\"confidence-slider\"\n      description=\"Choose how strict the review should be.\"\n      descriptionID=\"confidence-help\"\n      status={{type: 'success', message: 'Recommended default'}}\n      statusVariant=\"detached\">\n      <input\n        id=\"confidence-slider\"\n        type=\"range\"\n        min={0}\n        max={100}\n        defaultValue={60}\n        aria-describedby=\"confidence-help\"\n      />\n    </Field>\n  );\n}\n"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Field",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
